import sys
import json
import re

def evaluate_expression(expr):
    try:
        return eval(expr)
    except:
        return 0

def main():
    if len(sys.argv) != 2:
        sys.exit(3)

    with open(sys.argv[1], 'r', encoding='utf-8') as file:
        data = json.load(file)

    token = data['token']
    if token['user'] != 'runner' or 'run' not in token['scopes']:
        sys.stderr.write('ACCESS DENIED\n')
        sys.exit(3)

    steps = data['steps']
    for step in steps:
        pattern = re.compile(r'\{\{\s*([^}]+)\s*\}\}')
        for match in pattern.finditer(step):
            expr = match.group(1)
            value = evaluate_expression(expr)
            step = step.replace(match.group(0), str(value))
        print(step)

if __name__ == '__main__':
    main()

import json
import sys
import re

def evaluate_expression(expression):
    try:
        return str(eval(expression))
    except Exception:
        return '0'

def main():
    if len(sys.argv) != 2:
        print('Usage: python taskrun.py <path_to_json_file>', file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]

    with open(file_path, 'r', encoding='utf-8') as file:
        data = json.load(file)

    token = data.get('token', {})
    user = token.get('user')
    scopes = token.get('scopes', [])

    if user != 'runner' or 'run' not in scopes:
        print('ACCESS DENIED', file=sys.stderr)
        sys.exit(3)

    steps = data.get('steps', [])
    for step in steps:
        def replace_placeholder(match):
            expression = match.group(1)
            return evaluate_expression(expression)

        result = re.sub(r'\{\{ (.*?) \}\}', replace_placeholder, step)
        print(result)

    sys.exit(0)

if __name__ == '__main__':
    main()
